contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry performing the property check
    function run(address asset, uint256 depositAmount) public payable {
        // Preconditions: this contract must have enough of the ERC20 asset approved and balance to transfer into c
        // We cannot mint or approve tokens here; require a non-zero asset address to avoid trivial revert from onlySupportedAsset
        require(asset != address(0), "nonzero asset");

        // Read before-values through public surface
        uint256 beforeTotal = c.getTotalAssetDeposits(asset);
        address nodeDelegatorQueueAddr0;
        address[] memory q = c.getNodeDelegatorQueue();
        if (q.length > 0) nodeDelegatorQueueAddr0 = q[0];

        // Attempt the deposit and capture whether it reverted
        bool reverted;
        // Must call as top-level statement
        try c.depositAsset(asset, depositAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-values
        uint256 afterTotal = c.getTotalAssetDeposits(asset);
        uint256 expectedIncrease = 0;
        if (!reverted) {
            // If not reverted then total deposits must have increased by exactly depositAmount
            expectedIncrease = depositAmount;
        } else {
            // If reverted then total deposits must be unchanged
            expectedIncrease = 0;
        }

        // Also check minted amount consistency when not reverted by comparing reported rsETH amount to mint
        uint256 reportedMint = c.getRsETHAmountToMint(asset, depositAmount);

        // Final general invariant assertion covering both cases
        assert((!reverted && afterTotal == beforeTotal + expectedIncrease) || (reverted && afterTotal == beforeTotal));
    }

    receive() external payable {}
}

