contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test depositAsset(asset, depositAmount) behavior w.r.t. token balance of c.
    // Inputs: token address, depositAmount, and an address to act as token holder (spender).
    // The test will attempt to call depositAsset and observe whether it reverted and the change
    // in IERC20(asset).balanceOf(address(c)). We can only call public functions on c; we will
    // use getTotalAssetDeposits(asset) to observe total balances aggregated which includes
    // balance held by c (and others). However, getAssetDistributionData is only callable for
    // supported assets, so we conservatively observe IERC20(asset).balanceOf(address(c)) via
    // calling IERC20(asset).balanceOf which is allowed since IERC20 is declared in the compilation unit.

    // Note: to comply with constraints, all state-changing calls to c are top-level statements.
    function run(address asset, uint256 depositAmount, address spender) public payable {
        require(asset != address(0));

        // Observe balance before calling depositAsset
        uint256 before = IERC20(asset).balanceOf(address(c));

        bool reverted;
        // attempt the deposit; it may revert for many reasons (unsupported asset, paused, allowance, transfer fail, etc.)
        try c.depositAsset(asset, depositAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe balance after the call
        uint256 after = IERC20(asset).balanceOf(address(c));

        // General rule asserted:
        // If depositAsset reverted then the contract's token balance did not increase (after == before).
        // If depositAsset succeeded then the contract's token balance increased by exactly depositAmount (after == before + depositAmount).
        // This asserts atomicity: either no change on revert, or exact transfer of depositAmount on success.
        assert(reverted ? (after == before) : (after == before + depositAmount));
    }

    receive() external payable {}
}

