contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry running the property check
    // params:
    // asset - token contract address to deposit
    // depositAmount - amount to deposit
    // approver - address that will be used as msg.sender for approving token transfer (unused here because test contract itself is msg.sender to c)
    function run(address asset, uint256 depositAmount) public payable {
        require(asset != address(0));

        // Record old total deposits as observable through public API
        uint256 beforeTotal = c.getTotalAssetDeposits(asset);
        // Record c's token balance before (IERC20 balanceOf is public on token, but per constraints we may only call c's public surface;
        // however getAssetDistributionData returns deposit-pool balance as first item and is public and restricted to supported assets.
        // So we attempt to call getAssetDistributionData; it will revert if asset not supported. We'll catch that.
        bool supportedBefore;
        uint256 beforePoolBalance = 0;
        bool callReverted = false;
        try c.getAssetDistributionData(asset) returns (uint256 assetLyingInDepositPool, uint256, uint256) {
            supportedBefore = true;
            beforePoolBalance = assetLyingInDepositPool;
        } catch {
            supportedBefore = false;
        }

        // Attempt the deposit and capture whether it reverted
        bool reverted = false;
        try c.depositAsset(asset, depositAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // After-call observations
        uint256 afterTotal = 0;
        bool canReadAfter = true;
        try c.getTotalAssetDeposits(asset) returns (uint256 t) {
            afterTotal = t;
        } catch {
            canReadAfter = false;
        }

        bool supportedAfter;
        uint256 afterPoolBalance = 0;
        try c.getAssetDistributionData(asset) returns (uint256 assetLyingInDepositPool, uint256, uint256) {
            supportedAfter = true;
            afterPoolBalance = assetLyingInDepositPool;
        } catch {
            supportedAfter = false;
        }

        // General rule asserted below:
        // If depositAsset did NOT revert then:
        //  - asset must have been supported (so getAssetDistributionData callable)
        //  - depositAmount must be > 0 and <= getAssetCurrentLimit(asset) (these are preconditions enforced by the function)
        //  - c's observed total deposits (and pool balance) must have increased by at least depositAmount (i.e., tokens moved into contract)
        // If depositAsset reverted then either asset was unsupported or one of the function's require/revert conditions fired.
        assert(
            // case A: did not revert
            (!reverted) ? (
                // after reads must be available and asset supported
                canReadAfter && supportedAfter && supportedBefore
                // total deposits increased by at least depositAmount
                && (afterTotal >= beforeTotal + depositAmount)
                // pool balance increased by at least depositAmount
                && (afterPoolBalance >= beforePoolBalance + depositAmount)
            )
            // case B: reverted -> we allow revert (no further requirement)
            : true
        );
    }

    // allow receiving Ether if needed by tokens
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry running the property check
    // params:
    // asset - token contract address to deposit
    // depositAmount - amount to deposit
    function run(address asset, uint256 depositAmount) public payable {
        require(asset != address(0));

        // Try to read observable state before the call
        bool beforeSupported = true;
        uint256 beforePoolBalance = 0;
        uint256 beforeTotal = 0;
        // getTotalAssetDeposits is view and may revert if asset unsupported via getAssetDistributionData; wrap in try/catch
        try c.getAssetDistributionData(asset) returns (uint256 assetLyingInDepositPool, uint256 assetLyingInNDCs, uint256 assetStakedInEigenLayer) {
            beforePoolBalance = assetLyingInDepositPool;
            beforeTotal = c.getTotalAssetDeposits(asset);
        } catch {
            beforeSupported = false;
            // If unsupported, we still attempt to read total deposits separately (may also revert)
            try c.getTotalAssetDeposits(asset) returns (uint256 t) {
                beforeTotal = t;
            } catch {
                beforeTotal = 0;
            }
        }

        // Attempt the deposit and capture whether it reverted
        bool reverted = false;
        try c.depositAsset(asset, depositAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable state after the call if possible
        bool afterSupported = true;
        uint256 afterPoolBalance = 0;
        uint256 afterTotal = 0;
        try c.getAssetDistributionData(asset) returns (uint256 assetLyingInDepositPool, uint256, uint256) {
            afterPoolBalance = assetLyingInDepositPool;
            afterTotal = c.getTotalAssetDeposits(asset);
        } catch {
            afterSupported = false;
            try c.getTotalAssetDeposits(asset) returns (uint256 t) {
                afterTotal = t;
            } catch {
                afterTotal = beforeTotal;
            }
        }

        // Assert the general rule:
        // If depositAsset did not revert then asset must be supported (so getAssetDistributionData callable)
        // and both the pool balance and total deposits observed after are at least before + depositAmount.
        assert((!reverted) ? (
            // must be supported both before and after (observable)
            beforeSupported && afterSupported
            // after totals increased by at least depositAmount
            && (afterPoolBalance >= beforePoolBalance + depositAmount)
            && (afterTotal >= beforeTotal + depositAmount)
        ) : true);
    }

    receive() external payable {}
}

